/* xx_mcc_extractor.c - search raw data for MCC.
 *
 * Scans for:
 *   4D 43 43 00 at +0  ("MCC.")
 *   4D 43 43 01 at +0  ("MCC.")
 * Offset 0 is always tried as well.
 * Each candidate must be accepted by the mcc reader, which also measures it,
 * and named by the detector, both on a view that starts at the candidate.
 * See xx_format_extractor_engine.h.
 *
 * GENERATED by gen_extractors.py from the detector's prefilters.
 */

#include "../xx_format_extractor_engine.h"
#include "xxfclib/formats/mcc/xx_mcc.h"

static const uint8_t k_anchor0[] = { 0x4D, 0x43, 0x43, 0x00 };
static const uint8_t k_anchor1[] = { 0x4D, 0x43, 0x43, 0x01 };

static const xx_format_search_anchor k_anchors[] = {
    { k_anchor0, sizeof(k_anchor0), 0U },
    { k_anchor1, sizeof(k_anchor1), 0U },
};

static const xx_file_type_t k_types[] = { XX_FILE_TYPE_MCC };

static Abstractformat *xx_mcc_search_open(xx_io_device *window) {
    xx_mcc *reader = xx_mcc_create(window, 0);
    return reader ? &reader->format : NULL;
}

static void xx_mcc_search_close(Abstractformat *format) {
    /* The format is the first member, so this is the reader itself. */
    xx_mcc_free((xx_mcc *)format);
}

static const xx_format_search_desc k_desc = {
    k_types, sizeof(k_types) / sizeof(k_types[0]),
    k_anchors, sizeof(k_anchors) / sizeof(k_anchors[0]),
    xx_mcc_search_open, xx_mcc_search_close
};

static xx_format_search_state *xx_mcc_create_format_search(
    xx_format_extractor *self, xx_io_device *device, const xx_list_s *options,
    xx_pd_struct *pd) {
    (void)self;
    return xx_format_search_create(&k_desc, device, options, pd);
}

static const xx_format_search_info *xx_mcc_get_current_format_info(
    xx_format_extractor *self, xx_format_search_state *state) {
    (void)self;
    return xx_format_search_current(state);
}

static bool xx_mcc_format_search_find_next(xx_format_extractor *self,
                                          xx_format_search_state *state,
                                          xx_pd_struct *pd) {
    (void)self;
    return xx_format_search_find_next(state, pd);
}

static void xx_mcc_free_format_search(xx_format_extractor *self,
                                     xx_format_search_state *state) {
    (void)self;
    xx_format_search_free(state);
}

xx_format_extractor xx_mcc_extractor = {
    xx_mcc_create_format_search,
    xx_mcc_get_current_format_info,
    xx_mcc_format_search_find_next,
    xx_mcc_free_format_search
};
